int main(void)
{
    InitSysCtrl();
    InitGpio(); // Skipped for this example

    EALLOW;
    GpioCtrlRegs.GPCGMUX1.bit.GPIO67 = 0;
    GpioCtrlRegs.GPCDIR.bit.GPIO67 = 1;
    GpioDataRegs.GPCSET.bit.GPIO67 = 1;
    GpioCtrlRegs.GPCPUD.bit.GPIO67 = 0;
    GpioCtrlRegs.GPCCSEL1.bit.GPIO67 = 1;
    EDIS;

    GPIO_SetupPinOptions(18, GPIO_OUTPUT, GPIO_PUSHPULL);
    GPIO_SetupPinMux(18, GPIO_MUX_CPU1, 0);
    GPIO_SetupPinOptions(19, GPIO_OUTPUT, GPIO_PUSHPULL);
    GPIO_SetupPinMux(19, GPIO_MUX_CPU1, 0);

    DINT;
    // Initialize the PIE control registers to their default state.
    InitPieCtrl();

    // Disable CPU interrupts and clear all CPU interrupt flags:


    IER = 0x0000;
    IFR = 0x0000;

    InitPieVectTable();



    CLA_configClaMemory();
    CLA_initCpu1Cla1();

    EINT;  // Enable Global interrupt INTM
    ERTM;  // Enable Global realtime interrupt DBGM


    for(;;)
     {

        convolution_int16(input_image, workspace, conv1_weights, conv1_bias, IMAGE_SIZE,  IMAGE_SIZE, CONV1_WEIGHT_SCALE);

        relu_activation_int16( workspace,  MAX_ELEMENTS);

        max_pooling_int16(workspace, CONV_OUT_SIZE, CONV_OUT_SIZE, NUM_FILTERS);

        convolution_2_int16(workspace, &workspace[MAX_POLL_OUT_ELEMENT], conv2_weights, conv2_bias, CONV2_IN_SIZE, CONV2_IN_SIZE, CONV2_WEIGHT_SCALE);

        relu_activation_int16(&workspace[MAX_POLL_OUT_ELEMENT], NUM_FILTERS * CONV2_OUT_SIZE * CONV2_OUT_SIZE);

        max_pooling_2_int16(&workspace[MAX_POLL_OUT_ELEMENT], input_vector, CONV2_OUT_SIZE,  CONV2_OUT_SIZE, NUM_FILTERS);


        CLA_runTest();

     }

}



